import{_ as s,o as a,c as t,ag as o}from"./chunks/framework.D2veAa-g.js";const h=JSON.parse('{"title":"系统架构概述","description":"","frontmatter":{"title":"系统架构概述"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/绪论（第二版）/系统架构概述.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/绪论（第二版）/系统架构概述.md","lastUpdated":null}'),i={name:"架构师 在线刷题/51CT0题库 章节练习/绪论（第二版）/系统架构概述.md"};function r(n,l,c,e,u,g){return a(),t("div",null,[...l[0]||(l[0]=[o('<h1 id="系统架构概述-系统架构设计师" tabindex="-1">系统架构概述(系统架构设计师) <a class="header-anchor" href="#系统架构概述-系统架构设计师" aria-label="Permalink to &quot;系统架构概述(系统架构设计师)&quot;">​</a></h1><blockquote><p>共 17 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-采用以架构为核心的软件开发方法-在建立软件架构的初期-首要任务是选择一个合适的-请作答此空-在此基础上-开发人员通过架构模型-可以获得关于-的理解-为将来的架构实现与演化过程建立了目标。" tabindex="-1">Q1. 采用以架构为核心的软件开发方法，在建立软件架构的初期，首要任务是选择一个合适的（请作答此空），在此基础上，开发人员通过架构模型，可以获得关于（ ）的理解，为将来的架构实现与演化过程建立了目标。 <a class="header-anchor" href="#q1-采用以架构为核心的软件开发方法-在建立软件架构的初期-首要任务是选择一个合适的-请作答此空-在此基础上-开发人员通过架构模型-可以获得关于-的理解-为将来的架构实现与演化过程建立了目标。" aria-label="Permalink to &quot;Q1. 采用以架构为核心的软件开发方法，在建立软件架构的初期，首要任务是选择一个合适的（请作答此空），在此基础上，开发人员通过架构模型，可以获得关于（ ）的理解，为将来的架构实现与演化过程建立了目标。&quot;">​</a></h2><ul><li><strong>A.</strong> 分析模式</li><li><strong>B.</strong> 设计模式</li><li><strong>C.</strong> 架构风格</li><li><strong>D.</strong> 架构标准</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q2-架构是体现在组件中的一个系统的基本组织、它们-及指导它的设计和发展的原则。" tabindex="-1">Q2. 架构是体现在组件中的一个系统的基本组织、它们（ ）及指导它的设计和发展的原则。 <a class="header-anchor" href="#q2-架构是体现在组件中的一个系统的基本组织、它们-及指导它的设计和发展的原则。" aria-label="Permalink to &quot;Q2. 架构是体现在组件中的一个系统的基本组织、它们（ ）及指导它的设计和发展的原则。&quot;">​</a></h2><ul><li><strong>A.</strong> 访问的关系与操作系统的关系</li><li><strong>B.</strong> 调用的关系与运行时的关系</li><li><strong>C.</strong> 位置的关系与组织的关系</li><li><strong>D.</strong> 彼此的关系与环境的关系</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>架构是体现在组件中的一个系统的基本组织、它们彼此的关系与环境的关系及指导它的设计和发展的原则。</p></div></details><h2 id="q3-关于现代大型软件系统的架构设计-下列说法正确的是-。" tabindex="-1">Q3. 关于现代大型软件系统的架构设计，下列说法正确的是（ ）。 <a class="header-anchor" href="#q3-关于现代大型软件系统的架构设计-下列说法正确的是-。" aria-label="Permalink to &quot;Q3. 关于现代大型软件系统的架构设计，下列说法正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 必须严格遵循单一架构风格</li><li><strong>B.</strong> 混合多种架构风格，从不同视角描述系统</li><li><strong>C.</strong> 只能使用C/S或B/S架构风格</li><li><strong>D.</strong> 架构风格的选择与系统规模无关</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q4-某企业要开发一个具有较强用户交互功能的应用程序-最适合采用的架构风格是-。" tabindex="-1">Q4. 某企业要开发一个具有较强用户交互功能的应用程序，最适合采用的架构风格是（ ）。 <a class="header-anchor" href="#q4-某企业要开发一个具有较强用户交互功能的应用程序-最适合采用的架构风格是-。" aria-label="Permalink to &quot;Q4. 某企业要开发一个具有较强用户交互功能的应用程序，最适合采用的架构风格是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> SOA风格</li><li><strong>B.</strong> 虚拟机风格</li><li><strong>C.</strong> MVC风格</li><li><strong>D.</strong> 平台/插件风格</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>A：SOA风格主要用于企业集成<br> B：错误，虚拟机风格用于解释器或专家系统<br> C：正确，MVC风格专门用于用户交互程序的设计<br> D：错误，平台/插件风格主要用于具有插件扩展功能的应用程序</p><p>【教材依据】MVC风格用于用户交互程序的设计。因此本题的正确答案是C。</p></div></details><h2 id="q5-某系统需要将整个处理过程分解为多个独立的处理步骤-最适合采用的架构风格是-。" tabindex="-1">Q5. 某系统需要将整个处理过程分解为多个独立的处理步骤，最适合采用的架构风格是（ ）。 <a class="header-anchor" href="#q5-某系统需要将整个处理过程分解为多个独立的处理步骤-最适合采用的架构风格是-。" aria-label="Permalink to &quot;Q5. 某系统需要将整个处理过程分解为多个独立的处理步骤，最适合采用的架构风格是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> MVC风格</li><li><strong>B.</strong> 管道-过滤器风格</li><li><strong>C.</strong> C/S风格</li><li><strong>D.</strong> 虚拟机风格</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q6-关于软件架构中动态模型的特征-下列说法正确的是-。" tabindex="-1">Q6. 关于软件架构中动态模型的特征，下列说法正确的是（）。 <a class="header-anchor" href="#q6-关于软件架构中动态模型的特征-下列说法正确的是-。" aria-label="Permalink to &quot;Q6. 关于软件架构中动态模型的特征，下列说法正确的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 主要用于描述系统的静态结构</li><li><strong>B.</strong> 主要用于描述系统构造的具体步骤</li><li><strong>C.</strong> 是对结构或框架模型的补充，描述系统的重新配置或演化</li><li><strong>D.</strong> 仅用于描述系统的性能指标</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q7-下列关于软件架构建模方法的描述-错误的是-。" tabindex="-1">Q7. 下列关于软件架构建模方法的描述，错误的是（）。 <a class="header-anchor" href="#q7-下列关于软件架构建模方法的描述-错误的是-。" aria-label="Permalink to &quot;Q7. 下列关于软件架构建模方法的描述，错误的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 动态模型主要研究系统的重新配置或演化等&quot;大颗粒&quot;行为</li><li><strong>B.</strong> 框架模型比结构模型更侧重描述结构的细节</li><li><strong>C.</strong> 过程模型主要研究构造系统的步骤和过程</li><li><strong>D.</strong> 这四种模型需要有机结合才能完整描述软件架构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q8-某项目需要重点描述系统的构件、连接件等细节结构-应选择的建模方法是-。" tabindex="-1">Q8. 某项目需要重点描述系统的构件、连接件等细节结构，应选择的建模方法是（）。 <a class="header-anchor" href="#q8-某项目需要重点描述系统的构件、连接件等细节结构-应选择的建模方法是-。" aria-label="Permalink to &quot;Q8. 某项目需要重点描述系统的构件、连接件等细节结构，应选择的建模方法是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 框架模型</li><li><strong>B.</strong> 结构模型</li><li><strong>C.</strong> 动态模型</li><li><strong>D.</strong> 过程模型</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q9-架构风格用于gui软件开发-用以构建灵活和可扩展的应用系统等。" tabindex="-1">Q9. （）架构风格用于GUI软件开发，用以构建灵活和可扩展的应用系统等。 <a class="header-anchor" href="#q9-架构风格用于gui软件开发-用以构建灵活和可扩展的应用系统等。" aria-label="Permalink to &quot;Q9. （）架构风格用于GUI软件开发，用以构建灵活和可扩展的应用系统等。&quot;">​</a></h2><ul><li><strong>A.</strong> 管道-过滤器风格</li><li><strong>B.</strong> MVC风格</li><li><strong>C.</strong> SOA风格</li><li><strong>D.</strong> C2风格</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q10-下面不属于微服务架构分成三种实现模式-。" tabindex="-1">Q10. 下面不属于微服务架构分成三种实现模式（）。 <a class="header-anchor" href="#q10-下面不属于微服务架构分成三种实现模式-。" aria-label="Permalink to &quot;Q10. 下面不属于微服务架构分成三种实现模式（）。&quot;">​</a></h2><ul><li><strong>A.</strong> RESTful API模式</li><li><strong>B.</strong> RESTful应用模式</li><li><strong>C.</strong> 集中消息模式</li><li><strong>D.</strong> 分布式消息模式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q11-云架构-cloud-architecture-的主要特点是什么-。" tabindex="-1">Q11. 云架构（Cloud Architecture）的主要特点是什么（ ）。 <a class="header-anchor" href="#q11-云架构-cloud-architecture-的主要特点是什么-。" aria-label="Permalink to &quot;Q11. 云架构（Cloud Architecture）的主要特点是什么（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 低成本运维</li><li><strong>B.</strong> 高安全性</li><li><strong>C.</strong> 高扩展性</li><li><strong>D.</strong> 高可用性</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q12-在云架构中-负责将数据复制到每一个处理单元-确保数据同步的组件是-。" tabindex="-1">Q12. 在云架构中，负责将数据复制到每一个处理单元，确保数据同步的组件是（ ）。 <a class="header-anchor" href="#q12-在云架构中-负责将数据复制到每一个处理单元-确保数据同步的组件是-。" aria-label="Permalink to &quot;Q12. 在云架构中，负责将数据复制到每一个处理单元，确保数据同步的组件是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 消息中间件</li><li><strong>B.</strong> 数据中间件</li><li><strong>C.</strong> 处理中间件</li><li><strong>D.</strong> 部署中间件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q13-在云架构中-负责管理用户请求和会话控制-sessions-并决定将请求分配给哪一个处理单元的组件是-。" tabindex="-1">Q13. 在云架构中，负责管理用户请求和会话控制（sessions），并决定将请求分配给哪一个处理单元的组件是（ ）。 <a class="header-anchor" href="#q13-在云架构中-负责管理用户请求和会话控制-sessions-并决定将请求分配给哪一个处理单元的组件是-。" aria-label="Permalink to &quot;Q13. 在云架构中，负责管理用户请求和会话控制（sessions），并决定将请求分配给哪一个处理单元的组件是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 数据中间件</li><li><strong>B.</strong> 消息中间件</li><li><strong>C.</strong> 处理中间件</li><li><strong>D.</strong> 部署中间件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q14-在事件驱动架构-eda-中-负责将不同的事件分发到不同的业务逻辑单元的组件是-。" tabindex="-1">Q14. 在事件驱动架构（EDA）中，负责将不同的事件分发到不同的业务逻辑单元的组件是（ ）。 <a class="header-anchor" href="#q14-在事件驱动架构-eda-中-负责将不同的事件分发到不同的业务逻辑单元的组件是-。" aria-label="Permalink to &quot;Q14. 在事件驱动架构（EDA）中，负责将不同的事件分发到不同的业务逻辑单元的组件是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 事件队列</li><li><strong>B.</strong> 分发器</li><li><strong>C.</strong> 事件通道</li><li><strong>D.</strong> 事件处理器</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q15-在分层架构中-负责实现业务逻辑的是哪一层-。" tabindex="-1">Q15. 在分层架构中，负责实现业务逻辑的是哪一层（ ）。 <a class="header-anchor" href="#q15-在分层架构中-负责实现业务逻辑的是哪一层-。" aria-label="Permalink to &quot;Q15. 在分层架构中，负责实现业务逻辑的是哪一层（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 表现层</li><li><strong>B.</strong> 业务层</li><li><strong>C.</strong> 持久层</li><li><strong>D.</strong> 数据库层</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q16-微服务架构的实现模式中-哪种模式通常用于企业内部-背后是一个多功能的应用程序-。" tabindex="-1">Q16. 微服务架构的实现模式中，哪种模式通常用于企业内部，背后是一个多功能的应用程序（ ）。 <a class="header-anchor" href="#q16-微服务架构的实现模式中-哪种模式通常用于企业内部-背后是一个多功能的应用程序-。" aria-label="Permalink to &quot;Q16. 微服务架构的实现模式中，哪种模式通常用于企业内部，背后是一个多功能的应用程序（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> RESTful API模式</li><li><strong>B.</strong> RESTful应用模式</li><li><strong>C.</strong> 集中消息模式</li><li><strong>D.</strong> 分布式消息模式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q17-根据架构的定义-以下哪个选项最准确地描述了架构的核心要素-。" tabindex="-1">Q17. 根据架构的定义，以下哪个选项最准确地描述了架构的核心要素（ ）。 <a class="header-anchor" href="#q17-根据架构的定义-以下哪个选项最准确地描述了架构的核心要素-。" aria-label="Permalink to &quot;Q17. 根据架构的定义，以下哪个选项最准确地描述了架构的核心要素（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 系统的功能需求和性能指标</li><li><strong>B.</strong> 系统的组件、关系、环境和设计原则</li><li><strong>C.</strong> 系统的开发流程和测试方法</li><li><strong>D.</strong> 系统的用户界面和数据存储结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details>',53)])])}const m=s(i,[["render",r]]);export{h as __pageData,m as default};
